{"command":"cat > main.c <<'EOF'
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

const char *USAGE = "usage: java -jar ditaa.jar <INPFILE> [OUTFILE] [-A] [-b <BACKGROUND>] [-d]\n       [-E] [-e <ENCODING>] [-h] [--help] [-o] [-r] [-S] [-s <SCALE>]\n       [--svg] [--svg-font-url <FONT>] [-T] [-t <TABS>] [-v] [-W]\n -A,--no-antialias              Turns anti-aliasing off.\n -b,--background <BACKGROUND>   The background colour of the image. The\n                                format should be a six-digit hexadecimal\n                                number (as in HTML, FF0000 for red). Pass\n                                an eight-digit hex to define transparency.\n                                This is overridden by --transparent.\n -d,--debug                     Renders the debug grid over the resulting\n                                image.\n -E,--no-separation             Prevents the separation of common edges of\n                                shapes.\n -e,--encoding <ENCODING>       The encoding of the input file.\n -h,--html                      In this case the input is an HTML file.\n                                The contents of the <pre\n                                class=\"textdiagram\"> tags are rendered as\n                                diagrams and saved in the images directory\n                                and a new HTML file is produced with the\n                                appropriate <img> tags.\n    --help                      Prints usage help.\n -o,--overwrite                 If the filename of the destination image\n                                already exists, an alternative name is\n                                chosen. If the overwrite option is\n                                selected, the image file is instead\n                                overwriten.\n -r,--round-corners             Causes all corners to be rendered as round\n                                corners.\n -S,--no-shadows                Turns off the drop-shadow effect.\n -s,--scale <SCALE>             A natural number that determines the size\n                                of the rendered image. The units are\n                                fractions of the default size (2.5 renders\n                                1.5 times bigger than the default).\n    --svg                       Write an SVG image as destination file.\n    --svg-font-url <FONT>       SVG font URL.\n -T,--transparent               Causes the diagram to be rendered on a\n                                transparent background. Overrides\n                                --background.\n -t,--tabs <TABS>               Tabs are normally interpreted as 8 spaces\n                                but it is possible to change that using\n                                this option. It is not advisable to use\n                                tabs in your diagrams.\n -v,--verbose                   Makes ditaa more verbose.\n -W,--fixed-slope               Makes sides of parallelograms and\n                                trapezoids fixed slope instead of fixed\n                                width.\n";

int main(int argc, char **argv) {
    if (argc == 1) {
        printf("%s", USAGE);
        return 0;
    }
    // handle help
    if (strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "--help") == 0) {
        printf("%s", USAGE);
        return 0;
    }
    if (strcmp(argv[1], "--version") == 0) {
        printf("Unrecognized option: --version\n");
        printf("%s", USAGE);
        return 0;
    }
    // otherwise treat as filename
    const char *fname = argv[1];
    struct stat st;
    if (stat(fname, &st) != 0) {
        printf("\n");
        printf("ditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris\n\n");
        printf("Running with options:\n");
        printf("Reading file: %s\n", fname);
        printf("Error: File %s does not exist\n", fname);
        return 0;
    }
    // If file exists, just mimic no further processing: print header and then a message
    printf("\n");
    printf("ditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris\n\n");
    printf("Running with options:\n");
    printf("Reading file: %s\n", fname);
    printf("Output generation not implemented in this reimplementation.\n");
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/bin/sh
set -e
cc -O2 -static -s main.c -o executable || cc -O2 main.c -o executable
chmod +x executable
EOF

cat > .gitignore <<'EOF'
/executable
EOF

chmod +x compile.sh

# Build
./compile.sh

# Show produced file and run a few checks
ls -la executable
printf "\nRun no args:\n"
./executable | sed -n '1,120p'
printf "\nRun nonexist arg:\n"
./executable nonexist.txt | sed -n '1,120p'
printf "\nRun --version:\n"
./executable --version | sed -n '1,120p'

# Add files to git and commit
git add main.c compile.sh .gitignore
git commit -m "Reimplementation of ditaa CLI usage and basic behavior" || true

"}

